function F(name,dir,gap,o={}){const f=figma.createFrame();f.name=name;f.layoutMode=dir;f.itemSpacing=gap;f.fills=o.fill?sf(o.fill):[];f.primaryAxisSizingMode="AUTO";f.counterAxisSizingMode="AUTO";if(o.p!=null){f.paddingLeft=f.paddingRight=f.paddingTop=f.paddingBottom=o.p}if(o.px!=null){f.paddingLeft=f.paddingRight=o.px}if(o.py!=null){f.paddingTop=f.paddingBottom=o.py}if(o.r)f.cornerRadius=o.r;if(o.al)f.counterAxisAlignItems=o.al;return f}
function recolor(i,col){i.findAll(x=>"fills" in x&&x.type!=="TEXT"&&x.fills!==figma.mixed&&x.fills.length&&x.fills[0].type==="SOLID").forEach(x=>x.fills=sf(col));i.findAll(x=>"strokes" in x&&x.strokes.length&&x.strokes[0].type==="SOLID").forEach(x=>x.strokes=sf(col))}
function icon(n,size,col){const i=M[n].createInstance();i.resize(size,size);recolor(i,col);i.name=n;return i}
function fillScale(i){[i,...i.findAll(()=>true)].forEach(x=>{if("fills" in x&&x.fills!==figma.mixed&&x.fills.some(f=>f.type==="IMAGE"))x.fills=x.fills.map(f=>f.type==="IMAGE"?{...f,scaleMode:"FILL"}:f)})}
function img(n,w,h){const i=M[n].createInstance();i.resize(w,h);i.name=n;fillScale(i);return i}
function setT(inst,name,v){inst.findOne(n=>n.type==="TEXT"&&n.name===name).characters=v}
